package com.example.etl.validation

import com.example.etl.config.JobConfig
import com.example.etl.sql.SqlParserService // For optional SQL pre-check
import com.example.etl.util.SchemaMapper    // For validating schema_mapping_logic syntax
import org.apache.spark.sql.SparkSession
import org.apache.log4j.Logger
import scala.util.parsing.json.JSON
import scala.util.Try

object JobConfigValidator {

  @transient lazy val logger: Logger = Logger.getLogger(getClass.getName)

  private val SupportedTransformationModes = Set("AS_IS", "WITH_LOGIC", "SCD2")
  private val SupportedLoadTypes = Set("INCREMENTAL", "FULL_RELOAD")
  private val SupportedWriteModes = Set("overwrite", "append", "ignore", "errorifexists")
  private val SupportedSourceTypes = Set("FILE") // Extend as more are added
  private val SupportedTargetTypes = Set("FILE", "HDFS") // Extend as more are added
  private val SupportedFileFormats = Set("CSV", "PARQUET", "JSON", "ORC", "TEXT", "AVRO") // General list, context matters

  def validate(jobConfig: JobConfig, spark: SparkSession): List[String] = {
    var errors = List.empty[String]

    // Generic Mandatory Fields
    if (jobConfig.job_id == null || jobConfig.job_id.trim.isEmpty) errors :+= "job_id cannot be null or empty."
    if (jobConfig.job_name == null || jobConfig.job_name.trim.isEmpty) errors :+= "job_name cannot be null or empty."
    if (jobConfig.source_type == null || jobConfig.source_type.trim.isEmpty) errors :+= "source_type cannot be null or empty."
    else if (!SupportedSourceTypes.contains(jobConfig.source_type.toUpperCase)) errors :+= s"Unsupported source_type: '${jobConfig.source_type}'. Supported: ${SupportedSourceTypes.mkString(", ")}"\n    if (jobConfig.target_type == null || jobConfig.target_type.trim.isEmpty) errors :+= "target_type cannot be null or empty."
    else if (!SupportedTargetTypes.contains(jobConfig.target_type.toUpperCase)) errors :+= s"Unsupported target_type: '${jobConfig.target_type}'. Supported: ${SupportedTargetTypes.mkString(", ")}"\n    if (jobConfig.target_table_or_path == null || jobConfig.target_table_or_path.trim.isEmpty) errors :+= "target_table_or_path cannot be null or empty."
    if (jobConfig.transformation_mode == null || jobConfig.transformation_mode.trim.isEmpty) errors :+= "transformation_mode cannot be null or empty."
    else if (!SupportedTransformationModes.contains(jobConfig.transformation_mode.toUpperCase)) errors :+= s"Unsupported transformation_mode: '${jobConfig.transformation_mode}'. Supported: ${SupportedTransformationModes.mkString(", ")}"\n    if (jobConfig.load_type == null || jobConfig.load_type.trim.isEmpty) errors :+= "load_type cannot be null or empty."
    else if (!SupportedLoadTypes.contains(jobConfig.load_type.toUpperCase)) errors :+= s"Unsupported load_type: '${jobConfig.load_type}'. Supported: ${SupportedLoadTypes.mkString(", ")}"\n    if (jobConfig.target_write_mode == null || jobConfig.target_write_mode.trim.isEmpty) errors :+= "target_write_mode cannot be null or empty."
    else if (!SupportedWriteModes.contains(jobConfig.target_write_mode.toLowerCase)) errors :+= s"Unsupported target_write_mode: '${jobConfig.target_write_mode}'. Supported: ${SupportedWriteModes.mkString(", ")}"\n\n    // Source/Target Specifics\n    if (jobConfig.source_type.toUpperCase == "FILE") {\n      if (jobConfig.source_format.isEmpty || jobConfig.source_format.get.trim.isEmpty) errors :+= "source_format is mandatory for source_type 'FILE'."\n      else if (!SupportedFileFormats.contains(jobConfig.source_format.get.toUpperCase)) errors :+= s"Unsupported source_format: '${jobConfig.source_format.get}'. Check supported formats."\n      if (jobConfig.source_connection_details.isEmpty || jobConfig.source_connection_details.get.trim.isEmpty) errors :+= "source_connection_details (as path) is mandatory for source_type 'FILE'."\n    }\n    // Add similar checks for other source_types (KAFKA, JDBC) when implemented\n\n    // Transformation Mode Specifics\n    jobConfig.transformation_mode.toUpperCase match {\n      case "WITH_LOGIC" | "SCD2" =>\n        if (jobConfig.sql_logic.isEmpty || jobConfig.sql_logic.get.trim.isEmpty) {\n          errors :+= s"sql_logic is mandatory and cannot be empty for transformation_mode '${jobConfig.transformation_mode}'."\n        } else {\n          // Optional: Pre-emptive SQL syntax check (already done by handlers, but can be earlier)\n          // SqlParserService.parse(jobConfig.sql_logic.get, spark) match {\n          //   case Left(errMsg) => errors :+= s"SQL syntax error in sql_logic: $errMsg"\n          //   case Right(_) => // SQL syntax OK\n          // }\n        }\n      case _ => // AS_IS or other modes might not need sql_logic\n    }\n    if (jobConfig.transformation_mode.toUpperCase == "SCD2") {\n      if (jobConfig.scd2_natural_keys.isEmpty || jobConfig.scd2_natural_keys.get.trim.isEmpty) {\n        errors :+= "scd2_natural_keys is mandatory and cannot be empty for transformation_mode 'SCD2'."\n      }\n      // Could add checks for other scd2_*_column fields if they are non-Option in JobConfig or if specific names are disallowed\n    }\n\n    // schema_mapping_logic JSON Syntax Check\n    jobConfig.schema_mapping_logic.foreach { mappingJson =>\n      if (mappingJson.trim.nonEmpty) {\n        Try(SchemaMapper.parseMappingLogic(mappingJson)) match {\n          case Success(instructions) if mappingJson.trim.matches("\\s*\\{\\s*\\}\\s*") && instructions.nonEmpty => // Empty JSON object {} is valid and means no instructions\n             // This case is actually fine, it means an empty JSON object {} was correctly parsed as no instructions.\n          case Success(instructions) if instructions.isEmpty && !mappingJson.trim.matches("\\s*\\{\\s*\\}\\s*") =>\n            errors :+= "schema_mapping_logic is provided but resulted in no valid mapping instructions. Check JSON structure and content."\n          case Failure(ex) =>\n            errors :+= s"schema_mapping_logic is not valid JSON or has an internal parsing issue: ${ex.getMessage}"\n          case _ => // Parsed successfully\n        }\n      }\n    }\n\n    // job_properties JSON Syntax Check\n    jobConfig.job_properties.foreach { propsJson =>\n      if (propsJson.trim.nonEmpty) {\n        Try(JSON.parseFull(propsJson)) match {\n          case Success(Some(_: Map[_,_])) => // Successfully parsed as a Map\n          case Success(_) => errors :+= "job_properties is not a valid JSON object (e.g. {} or {\"key\":\"value\"})." // Parsed but not a Map\n          case Failure(ex) => errors :+= s"job_properties is not valid JSON: ${ex.getMessage}"\n        }\n      }\n    }\n\n    // Add more checks: e.g., numeric ranges for retry counts, SLA; regex for names; etc.\n\n    if (errors.nonEmpty) {\n      logger.error(s"Job configuration validation failed for job_id '${jobConfig.job_id}':\n - ${errors.mkString("\n - ")}")\n    }\n    errors\n  }\n}
